<?php require_once 'config.php'; if(is_login()){header('Location: dashboard.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $stmt=$pdo->prepare('SELECT * FROM users WHERE username=? LIMIT 1');$stmt->execute([trim($_POST['username']??'')]);$u=$stmt->fetch(); if($u && $u['password']===$_POST['password']){$_SESSION['login']=['id'=>$u['id'],'nama'=>$u['nama'],'username'=>$u['username'],'role'=>$u['role']];header('Location: dashboard.php');exit;} $error='Username atau password salah.'; }
